 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Output is the left 7-column drawing area. The 5 marks the starting
    # position; the vertical 4 divider separates it from the source symbols.
    out = [[0] * 7 for _ in range(h)]
    marker = next(( (r, c - 8) for r, row in enumerate(grid)
                    for c, value in enumerate(row) if value == 5), (0, 0))
    r, x = marker
    out[r][x] = 5

    # Each 3x3 symbol is a path command: direction and run length.
    commands = {
        (0b110, 0b101, 0b010): ('R', 3),
        (0b101, 0b101, 0b111): ('L', 2),
        (0b101, 0b010, 0b010): ('D', 2),
        (0b111, 0b010, 0b101): ('L', 4),
    }
    tiles = []
    # Commands are read down the left stack, then down the right stack.
    tops = list(range(0, h - 2, 4))
    for left in (0, 4):
        for top in tops:
            block = [grid[top+i][left:left+3] for i in range(3)]
            colors = {v for row in block for v in row if v != 0}
            if len(colors) != 1:
                continue
            color = next(iter(colors))
            signature = tuple(sum(1 << (2-j) for j, v in enumerate(row)
                                  if v == color) for row in block)
            if signature in commands:
                direction, length = commands[signature]
                tiles.append((color, direction, length))

    for color, direction, length in tiles:
        r += 1  # step down to the next path row before each command
        if direction in ('L', 'R'):
            dx = -1 if direction == 'L' else 1
            for k in range(length):
                xx = x + dx * k
                if 0 <= r < h and 0 <= xx < 7:
                    out[r][xx] = color
            x += dx * (length - 1)
        else:  # downward stroke, including the first row
            for k in range(length):
                rr = r + k
                if 0 <= rr < h and 0 <= x < 7:
                    out[rr][x] = color
            r += length - 1
    return out

